// countingWriter records how many times WriteHeader was called.
type countingWriter struct {
	*httptest.ResponseRecorder
	headerCalls int
}

func (c *countingWriter) WriteHeader(code int) {
	c.headerCalls++
	c.ResponseRecorder.WriteHeader(code)
}

func TestScratchFreshStatus(t *testing.T) {
	rec := &countingWriter{ResponseRecorder: httptest.NewRecorder()}
	w := &responseWriter{}
	w.reset(rec)
	if got := w.Status(); got != http.StatusOK {
		t.Errorf("fresh Status() = %d, want 200", got)
	}
	if w.Written() {
		t.Errorf("fresh Written() = true, want false")
	}
}

func TestScratchWriteHeader404(t *testing.T) {
	rec := &countingWriter{ResponseRecorder: httptest.NewRecorder()}
	w := &responseWriter{}
	w.reset(rec)
	w.WriteHeader(404)
	if got := w.Status(); got != 404 {
		t.Errorf("after WriteHeader(404) Status() = %d, want 404", got)
	}
}

