func reconstruct(fullPath string, params Params) string {
	out := fullPath
	for _, p := range params {
		if strings.HasPrefix(p.Key, "") {
			out = strings.Replace(out, ":"+p.Key, p.Value, 1)
			out = strings.Replace(out, "*"+p.Key, p.Value, 1)
		}
	}
	return out
}

