package gin

import (
	"fmt"
	"math/rand"
	"regexp"
	"strings"
	"testing"
)

// reference: does registered route R match path P case-insensitively?
func routeRegex(r string) *regexp.Regexp {
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(r); {
		c := r[i]
		if c == ':' {
			j := i + 1
			for j < len(r) && r[j] != '/' {
				j++
			}
			sb.WriteString("[^/]+")
			i = j
			continue
		}
		if c == '*' {
			sb.WriteString(".*")
			i = len(r)
			continue
		}
		sb.WriteString(regexp.QuoteMeta(string(c)))
		i++
	}
	sb.WriteString("$")
	return regexp.MustCompile("(?i)" + sb.String())
}

func ciMatchExists(routes []string, p string, fix bool) bool {
	for _, r := range routes {
		re := routeRegex(r)
		if re.MatchString(p) {
			return true
		}
		if fix {
			if strings.HasSuffix(p, "/") && re.MatchString(strings.TrimSuffix(p, "/")) {
				return true
			}
			if !strings.HasSuffix(p, "/") && re.MatchString(p+"/") {
				return true
			}
		}
	}
	return false
}

func TestZZCIFuzz(t *testing.T) {
	segments := []string{"a", "b", "ab", "Foo", "Bar", "baz", "x"}
	wilds := []string{":p", ":id", "*c", "*qux"}
	rnd := rand.New(rand.NewSource(12345))

	build := func(routes []string) (tree *node, ok bool) {
		tree = &node{}
		defer func() {
			if rec := recover(); rec != nil {
				ok = false
			}
		}()
		for _, r := range routes {
			tree.addRoute(r, fakeHandler(r))
		}
		return tree, true
	}

	problems := 0
	for iter := 0; iter < 4000; iter++ {
		nseg := 1 + rnd.Intn(2)
		var routes []string
		for s := 0; s < nseg; s++ {
			seg := segments[rnd.Intn(len(segments))]
			if rnd.Intn(4) == 0 {
				seg = wilds[rnd.Intn(len(wilds))]
			}
			routes = append(routes, "/"+seg)
		}
		// add a deeper route sometimes
		if rnd.Intn(2) == 0 {
			routes = append(routes, "/"+segments[rnd.Intn(len(segments))]+"/"+segments[rnd.Intn(len(segments))])
		}
		if rnd.Intn(3) == 0 {
			routes = append(routes, "/"+segments[rnd.Intn(len(segments))]+"/"+wilds[rnd.Intn(len(wilds))])
		}
		tree, ok := build(routes)
		if !ok {
			continue
		}
		// candidate lookups: case variants of routes + random junk
		var lookups []string
		for _, r := range routes {
			lookups = append(lookups, r, strings.ToUpper(r), strings.ToLower(r))
			lookups = append(lookups, r+"/", strings.ToUpper(r)+"/")
		}
		lookups = append(lookups, "/", "//", "/zzz", "/ZZZ", "/A/B/C")

		for _, p := range lookups {
			for _, fix := range []bool{true, false} {
				var out []byte
				var found bool
				var panicked interface{}
				func() {
					defer func() { panicked = recover() }()
					out, found = tree.findCaseInsensitivePath(p, fix)
				}()
				if panicked != nil {
					t.Errorf("iter=%d routes=%v lookup=%q fix=%v PANIC %v", iter, routes, p, fix, panicked)
					problems++
					if problems > 10 {
						return
					}
					continue
				}
				if found {
					// returned path must be a live route
					v := tree.getValue(string(out), nil, getSkippedNodes(), false)
					if v.handlers == nil {
						t.Errorf("iter=%d routes=%v lookup=%q fix=%v -> %q but getValue finds nothing", iter, routes, p, fix, string(out))
						problems++
					}
				} else {
					if ciMatchExists(routes, p, fix) {
						t.Errorf("iter=%d routes=%v lookup=%q fix=%v -> not found, but a case-insensitive route match exists", iter, routes, p, fix)
						problems++
					}
				}
				if problems > 10 {
					return
				}
			}
		}
	}
	fmt.Println("done, problems:", problems)
}
EOF
